import * as THREE from 'three';

/**
 * Coordinate / time conventions
 * -----------------------------
 * World axes (right-handed, Y = up):
 *   +X = west,  -X = east
 *   +Z = south, -Z = north
 *
 * Sun model (computed, not rendered):
 *   The sun travels on a circle over the dial. Its azimuth is measured
 *   from due south (+Z), positive toward the west (+X):
 *
 *       azimuth(hour) = PI * (hourOfDay - 12) / 6      [radians]
 *
 *     so hour 12 => azimuth 0 (due south), hour 6/18 => ∓PI/2 (east/west).
 *
 *   Elevation: define the "day fraction" f as the fraction of the daylight
 *   span (sunrise at hour 6, sunset at hour 18) that has elapsed:
 *
 *       f = (hourOfDay - 6) / 12          f ∈ [0, 1]
 *
 *   Elevation rises and falls sinusoidally with f, peaking at 60 degrees
 *   at noon (f = 0.5):
 *
 *       elevation(hour) = (60 deg) * sin(PI * f)
 *                       = (PI/3 rad) * sin(PI * (hourOfDay - 6) / 12)
 *
 * sunDirection() returns a unit vector pointing FROM the origin TOWARD
 * the sun under these conventions.
 */

const DEG2RAD = Math.PI / 180;

/**
 * Unit vector pointing toward the sun at the given hour.
 * @param {number} hourOfDay - decimal hours; meaningful range [6, 18]
 * @returns {THREE.Vector3} unit sun direction
 */
export function sunDirection(hourOfDay) {
  const azimuth = Math.PI * (hourOfDay - 12) / 6;
  const dayFraction = (hourOfDay - 6) / 12;
  const elevation = (60 * DEG2RAD) * Math.sin(Math.PI * dayFraction);

  return new THREE.Vector3(
    Math.sin(azimuth) * Math.cos(elevation), // west(+x)/east(-x)
    Math.sin(elevation),                      // up
    Math.cos(azimuth) * Math.cos(elevation), // south(+z)/north(-z)
  );
}

/**
 * Normalized horizontal projection of the negated sun direction — i.e.
 * the direction on the dial plane in which a shadow is cast.
 * Result always has y === 0 and length === 1.
 * @param {number} hour
 * @returns {THREE.Vector3}
 */
export function shadowDir(hour) {
  const sun = sunDirection(hour);
  const shadow = new THREE.Vector3(-sun.x, 0, -sun.z);
  if (shadow.lengthSq() < 1e-20) {
    // Sun exactly overhead: shadow direction is undefined; pick north.
    return new THREE.Vector3(0, 0, -1);
  }
  return shadow.normalize();
}

/**
 * Build the sundial asset.
 *
 * Structure:
 *   - base:  a cylindrical disc (dial plate), bottom at y = 0,
 *            top face at y = BASE_THICKNESS
 *   - gnomon:a triangular custom BufferGeometry standing vertically in
 *            the x = 0 plane along the north-south axis; its hypotenuse
 *            (the style that casts the reading edge) makes an angle of
 *            exactly latitudeDeg with the dial plane
 *   - ticks: 13 flat marks for hours 6..18 lying ON the dial top face
 *            (coplanar with it)
 *
 * @param {{latitudeDeg?: number}} options
 * @returns {{group: THREE.Group, base: THREE.Mesh, gnomon: THREE.Mesh, ticks: THREE.Mesh[]}}
 */
export function buildSundial({ latitudeDeg = 45 } = {}) {
  const group = new THREE.Group();

  const RADIUS = 1;
  const BASE_THICKNESS = 0.05;

  // --- Base disc -----------------------------------------------------------
  const baseGeometry = new THREE.CylinderGeometry(RADIUS, RADIUS, BASE_THICKNESS, 64);
  baseGeometry.translate(0, BASE_THICKNESS / 2, 0); // bottom at y=0, top at y=BASE_THICKNESS
  const base = new THREE.Mesh(baseGeometry, new THREE.MeshStandardMaterial({ color: 0xcccccc }));
  group.add(base);

  // --- Gnomon (custom BufferGeometry) --------------------------------------
  // Right triangle in the x = 0 plane. Base runs along Z of length 1,
  // vertical edge at the south end of height tan(latitude). The hypotenuse
  // therefore makes an angle atan(tan(lat)/1) = lat with the dial plane.
  const latRad = latitudeDeg * DEG2RAD;
  const gnomonHeight = Math.tan(latRad);

  const v0 = [0, 0, -0.5];                       // north end of base
  const v1 = [0, 0, 0.5];                        // south end of base
  const v2 = [0, gnomonHeight, -0.5];            // apex above north end

  const gnomonGeometry = new THREE.BufferGeometry();
  gnomonGeometry.setAttribute(
    'position',
    new THREE.Float32BufferAttribute([...v0, ...v1, ...v2], 3),
  );
  gnomonGeometry.computeVertexNormals();
  const gnomon = new THREE.Mesh(gnomonGeometry, new THREE.MeshStandardMaterial({
    color: 0x333333,
    side: THREE.DoubleSide,
  }));
  group.add(gnomon);

  // --- Hour tick marks (13 marks, hours 6..18) ------------------------------
  // Each tick is a flat quad (PlaneGeometry rotated into the XZ plane so all
  // its vertices share y = BASE_THICKNESS, coplanar with the dial top face).
  const TICK_LENGTH = 0.12;
  const TICK_WIDTH = 0.02;
  const TICK_RADIUS = 0.85; // radial distance of tick centers from center

  const ticks = [];
  for (let hour = 6; hour <= 18; hour++) {
    const tickGeometry = new THREE.PlaneGeometry(TICK_WIDTH, TICK_LENGTH);
    // Rotate flat: plane normal +Y, long axis radial after placement.
    tickGeometry.rotateX(-Math.PI / 2);
    const dir = shadowDir(24 - hour); // opposite the shadow = toward the sun's horizontal bearing
    tickGeometry.translate(dir.x * TICK_RADIUS, BASE_THICKNESS + 0.0005, dir.z * TICK_RADIUS);
    // Point the tick's long axis radially.
    tickGeometry.rotateY(Math.atan2(dir.x, dir.z)); // no-op visually for a symmetric quad, kept explicit

    const tick = new THREE.Mesh(tickGeometry, new THREE.MeshBasicMaterial({ color: 0x222222, side: THREE.DoubleSide }));
    ticks.push(tick);
    group.add(tick);
  }

  return { group, base, gnomon, ticks };
}

