import { describe, it, expect } from 'vitest';
import * as THREE from 'three';
import { buildSundial, sunDirection, shadowDir } from '../src/sundial.js';

const EPS = 1e-9;

describe('sunDirection', () => {
  it('is a unit vector', () => {
    for (let h = 6; h <= 18; h += 0.5) {
      expect(sunDirection(h).length()).toBeCloseTo(1, 12);
    }
  });
});

describe('shadowDir', () => {
  it('at hour 12 points due north (0, 0, -1) within 1e-9', () => {
    const s = shadowDir(12);
    expect(Math.abs(s.x)).toBeLessThanOrEqual(EPS);
    expect(Math.abs(s.y)).toBeLessThanOrEqual(EPS);
    // s.z must equal exactly -1 within 1e-9
    expect(s.z).toBeGreaterThanOrEqual(-1 - EPS);
    expect(s.z).toBeLessThanOrEqual(-1 + EPS);
    // explicit component check
    expect(s.x).toBeCloseTo(0, 9);
    expect(s.y).toBeCloseTo(0, 9);
    expect(s.z).toBeCloseTo(-1, 9);
  });

  it('at hours 9 and 15 the shadows are mirror images in x within 1e-9', () => {
    const morning = shadowDir(9);
    const evening = shadowDir(15);
    expect(Math.abs(morning.x + evening.x)).toBeLessThanOrEqual(EPS);
    expect(Math.abs(morning.y - evening.y)).toBeLessThanOrEqual(EPS);
    expect(Math.abs(morning.z - evening.z)).toBeLessThanOrEqual(EPS);
  });

  it('all shadow vectors are unit length with zero y', () => {
    for (let h = 6; h <= 18; h += 0.25) {
      const s = shadowDir(h);
      expect(s.y).toBeCloseTo(0, 12);
      expect(s.length()).toBeCloseTo(1, 12);
    }
  });
});

describe('buildSundial', () => {
  const { base, gnomon, ticks } = buildSundial({ latitudeDeg: 45 });

  it('has exactly 13 tick marks', () => {
    expect(ticks.length).toBe(13);
  });

  it('ticks are coplanar with the base top face within 1e-9', () => {
    // Base top face: cylinder of height BASE_THICKNESS translated up by
    // half its height -> all top-cap vertices share y = BASE_THICKNESS.
    const basePos = base.geometry.attributes.position;
    let baseTopY = -Infinity;
    for (let i = 0; i < basePos.count; i++) {
      baseTopY = Math.max(baseTopY, basePos.getY(i));
    }

    for (const tick of ticks) {
      const p = tick.geometry.attributes.position;
      for (let i = 0; i < p.count; i++) {
        expect(Math.abs(p.getY(i) - baseTopY)).toBeLessThanOrEqual(EPS);
      }
    }
  });

  it("gnomon's hypotenuse angle equals latitudeDeg within 1e-6", () => {
    for (const latDeg of [10, 30, 45, 60, 80]) {
      const { gnomon } = buildSundial({ latitudeDeg: latDeg });
      const p = gnomon.geometry.attributes.position;
      const verts = [];
      for (let i = 0; i < p.count; i++) {
        verts.push(new THREE.Vector3(p.getX(i), p.getY(i), p.getZ(i)));
      }
      expect(verts.length).toBe(3);

      // Hypotenuse = longest edge of the triangle.
      let hypA;
      let hypB;
      let maxLenSq = -1;
      for (let i = 0; i < verts.length; i++) {
        for (let j = i + 1; j < verts.length; j++) {
          const d = verts[i].distanceToSquared(verts[j]);
          if (d > maxLenSq) {
            maxLenSq = d;
            [hypA, hypB] = [verts[i], verts[j]];
          }
        }
      }

      const rise = Math.abs(hypA.y - hypB.y);
      const run = Math.hypot(hypA.x - hypB.x, hypA.z - hypB.z);
      const angleDeg = THREE.MathUtils.radToDeg(Math.atan2(rise, run));
      expect(angleDeg).toBeCloseTo(latDeg, 6);
    }
  });
});

